// catalog-check (foundation-contracts, S0). Guard the committed synthetic catalog
// (build plan section 6, ADR-016). It:
//   1. regenerates the catalog and its index from fixtures/synthetic/generate.ts
//      (deterministic: fixed seed, sorted iteration, byte-stable serialization);
//   2. compares the regenerated bytes to the committed fixtures/synthetic/
//      catalog.json and index.json, byte for byte;
//   3. validates every committed session against the live SessionWireSchema,
//      reporting the first failing session index with its field path on mismatch.
//
// Run with "--write" to (re)emit the committed files from the generator. Run with
// no argument (the check mode) to verify the committed files match and validate.
//
// The generator and the contracts schema are TypeScript; Node 24 imports them
// directly via native type stripping, so there is no build step. Dependency free
// beyond the in-repo generator and the contracts zod schema.

import { readFile, writeFile } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const thisDir = dirname(fileURLToPath(import.meta.url));
const repoRoot = resolve(thisDir, '..', '..');
const syntheticDir = resolve(repoRoot, 'fixtures', 'synthetic');

export const CATALOG_PATH = resolve(syntheticDir, 'catalog.json');
export const INDEX_PATH = resolve(syntheticDir, 'index.json');

const generatorUrl = pathToFileURL(resolve(syntheticDir, 'generate.ts')).href;
const sessionSchemaUrl = pathToFileURL(
  resolve(repoRoot, 'packages', 'contracts', 'src', 'wire', 'session.ts'),
).href;

/**
 * Regenerate the catalog and index as byte-stable JSON strings.
 *
 * @returns {Promise<{ catalog: string, index: string, sessions: unknown[] }>}
 */
export async function regenerate() {
  const gen = await import(generatorUrl);
  const sessions = gen.generateCatalog();
  const index = gen.buildIndex(sessions);
  return {
    catalog: gen.stableStringify(sessions),
    index: gen.stableStringify(index),
    sessions,
  };
}

/**
 * Write the committed catalog and index from the generator (the --write path).
 *
 * @returns {Promise<{ catalogBytes: number, indexBytes: number, count: number }>}
 */
export async function emit() {
  const { catalog, index, sessions } = await regenerate();
  await writeFile(CATALOG_PATH, catalog, 'utf8');
  await writeFile(INDEX_PATH, index, 'utf8');
  return {
    catalogBytes: Buffer.byteLength(catalog, 'utf8'),
    indexBytes: Buffer.byteLength(index, 'utf8'),
    count: sessions.length,
  };
}

/**
 * Check the committed files against the regenerated output and validate every
 * committed session against SessionWireSchema.
 *
 * @returns {Promise<{ ok: boolean, problems: string[] }>}
 */
export async function check() {
  const problems = [];
  const { catalog, index } = await regenerate();

  let committedCatalog;
  let committedIndex;
  try {
    committedCatalog = await readFile(CATALOG_PATH, 'utf8');
    committedIndex = await readFile(INDEX_PATH, 'utf8');
  } catch (cause) {
    const reason = cause instanceof Error ? cause.message : String(cause);
    problems.push(`cannot read a committed catalog file: ${reason}`);
    return { ok: false, problems };
  }

  if (committedCatalog !== catalog) {
    problems.push('catalog.json does not match the generator output (byte mismatch)');
  }
  if (committedIndex !== index) {
    problems.push('index.json does not match the generator output (byte mismatch)');
  }

  // Validate every committed session against the live schema, reporting the first
  // failing index with its field path.
  const { SessionWireSchema } = await import(sessionSchemaUrl);
  let parsed;
  try {
    parsed = JSON.parse(committedCatalog);
  } catch (cause) {
    const reason = cause instanceof Error ? cause.message : String(cause);
    problems.push(`committed catalog.json is not valid JSON: ${reason}`);
    return { ok: false, problems };
  }

  if (!Array.isArray(parsed)) {
    problems.push('committed catalog.json is not a JSON array');
    return { ok: false, problems };
  }

  for (let i = 0; i < parsed.length; i += 1) {
    const result = SessionWireSchema.safeParse(parsed[i]);
    if (!result.success) {
      const issue = result.error.issues[0];
      const path = issue ? issue.path.join('.') : '(unknown path)';
      problems.push(`session index ${i} fails SessionWireSchema at field "${path}"`);
      break;
    }
  }

  return { ok: problems.length === 0, problems };
}

const invokedDirectly =
  process.argv[1] !== undefined && import.meta.url === pathToFileURL(process.argv[1]).href;

if (invokedDirectly) {
  const mode = process.argv[2];
  if (mode === '--write') {
    emit()
      .then((r) => {
        process.stdout.write(
          `wrote catalog.json (${r.catalogBytes} bytes) and index.json (${r.indexBytes} bytes) for ${r.count} sessions\n`,
        );
      })
      .catch((error) => {
        process.stderr.write(`${error.message}\n`);
        process.exitCode = 1;
      });
  } else {
    check()
      .then(({ ok, problems }) => {
        if (ok) {
          process.stdout.write('catalog check ok: committed catalog matches and validates\n');
          return;
        }
        process.stderr.write('catalog check FAILED:\n');
        for (const p of problems) {
          process.stderr.write(`  ${p}\n`);
        }
        process.exitCode = 1;
      })
      .catch((error) => {
        process.stderr.write(`${error.message}\n`);
        process.exitCode = 1;
      });
  }
}
